// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
   ghost smooth solid S -> ExtrudeGeometry(area under h(x), depth 1.6)  pink 0.18, no depthWrite
   red outline of S     -> Line / LineSegments polylines                #E23B3B
   slabs S1..Sn         -> BoxGeometry(dx, h(x*), 1.6) MeshBasic pink   #F7CFCF, 0.62
   highlighted slab     -> same box, blue #7FB3DC 0.72 + edges #3C7CB4
   partition cut lines  -> EdgesGeometry per slab, thin black #1A1A1A
   base x-axis          -> Line + ConeGeometry arrowhead + tick LineSegments (black)
   zoom slab Sk         -> BoxGeometry scaled ~1.6, blue + dark blue EdgesGeometry
   neighbour shells     -> EdgesGeometry boxes, gray #9A9A9A
   cross-section face   -> PlaneGeometry(D,h) facing -X, blue tint
   cross-section mark   -> BoxGeometry(0.05,h,0.05) black (thick vertical line)
   dot at x*_k          -> SphereGeometry(0.075) black
   zoom axis            -> Line + cone, label x
   Δx_k dimension       -> Lines + two ConeGeometry arrows pointing inward
   callout              -> HTML label (tan box #FAE3B0/#D8A63F) + ExtrudeGeometry block arrow
   sweeping connector   -> TubeGeometry(CatmullRomCurve3) + cone head, tan #F1DCAA
   all text             -> addLabel HTML overlays
──────────────────────────────────────────────────────────────────────────── */

const A_ = -3, B_ = 3, D_ = 1.6;
const hFun = x => 0.7 + 1.5 * Math.sqrt(Math.max(0, (x - A_) / (B_ - A_)));
const AreaFun = x => D_ * hFun(x);

let V_EXACT = 0;
{ const N = 20000, dxe = (B_ - A_) / N; for (let i = 0; i < N; i++) V_EXACT += AreaFun(A_ + (i + 0.5) * dxe) * dxe; }

/* ── materials (flat, print-like colours) ───────────────────────────────── */
const faceOpts = { transparent: true, side: THREE.FrontSide, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 };
const pinkMat = new THREE.MeshBasicMaterial({ color: 0xF7CFCF, opacity: 0.62, ...faceOpts });
const pinkTop = new THREE.MeshBasicMaterial({ color: 0xFBE2E2, opacity: 0.62, ...faceOpts });
const blueMat = new THREE.MeshBasicMaterial({ color: 0x7FB3DC, opacity: 0.74, ...faceOpts });
const ghostMat = new THREE.MeshBasicMaterial({ color: 0xF7CFCF, transparent: true, opacity: 0.20, depthWrite: false, side: THREE.DoubleSide });
const redEdge = new THREE.LineBasicMaterial({ color: 0xE23B3B });
const cutEdge = new THREE.LineBasicMaterial({ color: 0x1A1A1A, transparent: true, opacity: 0.9 });
const cutEdgeFaint = new THREE.LineBasicMaterial({ color: 0x1A1A1A, transparent: true, opacity: 0.35 });
const blueEdge = new THREE.LineBasicMaterial({ color: 0x3C7CB4 });
const grayEdge = new THREE.LineBasicMaterial({ color: 0x9A9A9A, transparent: true, opacity: 0.9 });
const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
const csFaceMat = new THREE.MeshBasicMaterial({ color: 0x2A6496, transparent: true, opacity: 0.28, depthWrite: false, side: THREE.DoubleSide });
const tanMat = new THREE.MeshBasicMaterial({ color: 0xF1DCAA });
const tanEdge = new THREE.LineBasicMaterial({ color: 0xB9B0A0 });

/* ── groups ─────────────────────────────────────────────────────────────── */
const mainGroup = new THREE.Group();
const zoomGroup = new THREE.Group();
const connGroup = new THREE.Group();

/* ── helpers ────────────────────────────────────────────────────────────── */
function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse && c.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
}
function clearLabels() { for (const e of _labels) e.div.remove(); _labels.length = 0; }
function polyline(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function segs(pairs, mat) {
  const p = []; for (const q of pairs) { p.push(q[0], q[1]); }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(p), mat);
}
function coneAt(pos, dir, r, h, mat) {
  const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, 18), mat);
  c.position.copy(pos);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return c;
}
function blockArrow(len, shaftH, headH, headL, mat) {
  const s = new THREE.Shape();
  s.moveTo(0, -shaftH / 2); s.lineTo(len - headL, -shaftH / 2); s.lineTo(len - headL, -headH / 2);
  s.lineTo(len, 0); s.lineTo(len - headL, headH / 2); s.lineTo(len - headL, shaftH / 2);
  s.lineTo(0, shaftH / 2); s.closePath();
  const g = new THREE.ExtrudeGeometry(s, { depth: 0.05, bevelEnabled: false });
  return new THREE.Mesh(g, mat);
}
const V = (x, y, z) => new THREE.Vector3(x, y, z);

/* ── state ──────────────────────────────────────────────────────────────── */
let n = 6;
let selFrac = 2.5 / 6;          // 3rd slab of 6, as in the source figure
let view = 'side';              // the printed figure shows BOTH panels
let kIdx = 2;
const slabMeshes = [];
function syncK() { kIdx = Math.max(0, Math.min(n - 1, Math.floor(selFrac * n))); }

/* ── main solid (left panel) ────────────────────────────────────────────── */
function buildMain() {
  clearGroup(mainGroup);
  slabMeshes.length = 0;
  const dx = (B_ - A_) / n;
  const hlIdx = n > 1 ? kIdx : -1;          // a single slab IS the solid → keep it pink

  /* faint ghost of the true smooth solid */
  const sh = new THREE.Shape();
  sh.moveTo(A_, 0); sh.lineTo(B_, 0); sh.lineTo(B_, hFun(B_));
  const NS = 70;
  for (let i = NS; i >= 0; i--) { const x = A_ + (B_ - A_) * i / NS; sh.lineTo(x, hFun(x)); }
  sh.lineTo(A_, 0);
  const gg = new THREE.ExtrudeGeometry(sh, { depth: D_, bevelEnabled: false });
  gg.translate(0, 0, -D_ / 2);
  const ghost = new THREE.Mesh(gg, ghostMat); ghost.renderOrder = -1;
  mainGroup.add(ghost);

  /* red outline of the true solid */
  const topF = [], topB = [];
  for (let i = 0; i <= NS; i++) { const x = A_ + (B_ - A_) * i / NS; topF.push(V(x, hFun(x), D_ / 2)); topB.push(V(x, hFun(x), -D_ / 2)); }
  mainGroup.add(polyline(topF, redEdge), polyline(topB, redEdge));
  mainGroup.add(segs([
    [V(A_, 0, D_ / 2), V(B_, 0, D_ / 2)], [V(A_, 0, -D_ / 2), V(B_, 0, -D_ / 2)],
    [V(A_, 0, -D_ / 2), V(A_, 0, D_ / 2)], [V(B_, 0, -D_ / 2), V(B_, 0, D_ / 2)],
    [V(A_, 0, D_ / 2), V(A_, hFun(A_), D_ / 2)], [V(A_, 0, -D_ / 2), V(A_, hFun(A_), -D_ / 2)],
    [V(B_, 0, D_ / 2), V(B_, hFun(B_), D_ / 2)], [V(B_, 0, -D_ / 2), V(B_, hFun(B_), -D_ / 2)],
    [V(A_, hFun(A_), -D_ / 2), V(A_, hFun(A_), D_ / 2)], [V(B_, hFun(B_), -D_ / 2), V(B_, hFun(B_), D_ / 2)]
  ], redEdge));

  /* the flat-topped slabs */
  const em = n > 12 ? cutEdgeFaint : cutEdge;
  for (let i = 0; i < n; i++) {
    const xm = A_ + (i + 0.5) * dx, hh = hFun(xm);
    const bg = new THREE.BoxGeometry(dx, hh, D_);
    const mesh = new THREE.Mesh(bg, i === hlIdx ? blueMat : pinkMat);
    mesh.position.set(xm, hh / 2, 0);
    mesh.renderOrder = 1;
    const eg = new THREE.LineSegments(new THREE.EdgesGeometry(bg), i === hlIdx ? blueEdge : em);
    eg.position.copy(mesh.position);
    mainGroup.add(mesh, eg);
    slabMeshes.push(mesh);
    registerInteractive(mesh, {
      title: `Slab S${i + 1}`,
      tooltip: `S${i + 1}:  A ≈ ${AreaFun(xm).toFixed(2)},  Δx = ${dx.toFixed(2)}`,
      body: `Slab S${i + 1} sits over [${(A_ + i * dx).toFixed(2)}, ${(A_ + (i + 1) * dx).toFixed(2)}]. ` +
        `Its sample point is x* = ${xm.toFixed(2)}, its cross-sectional area is A(x*) = ${AreaFun(xm).toFixed(3)}, ` +
        `and its thickness is Δx = ${dx.toFixed(3)}, so its volume is about ${(AreaFun(xm) * dx).toFixed(3)}.`,
      onClick: () => { selFrac = (xm - A_) / (B_ - A_); rebuild(false); }
    });
  }

  /* x-axis, ticks, arrowhead */
  const ya = -0.15, za = D_ / 2 + 0.25;
  mainGroup.add(polyline([V(-4, ya, za), V(4, ya, za)], blackLine));
  mainGroup.add(coneAt(V(4.14, ya, za), V(1, 0, 0), 0.09, 0.28, blackMat));
  const tk = [];
  for (let i = 0; i <= n; i++) { const x = A_ + i * dx; tk.push([V(x, ya - 0.12, za), V(x, ya + 0.12, za)]); }
  mainGroup.add(segs(tk, blackLine));
}

/* ── zoom panel (right) ─────────────────────────────────────────────────── */
function buildZoom() {
  clearGroup(zoomGroup);
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx, hk = hFun(xm);

  /* gray wireframe shells of the neighbouring slabs */
  for (const off of [-1, 1]) {
    const j = kIdx + off; if (j < 0 || j >= n) continue;
    const hj = hFun(A_ + (j + 0.5) * dx);
    const g = new THREE.BoxGeometry(dx, hj, D_);
    const e = new THREE.LineSegments(new THREE.EdgesGeometry(g), grayEdge);
    e.position.set(off * dx, hj / 2, 0);
    zoomGroup.add(e); g.dispose();
  }

  /* the slab itself */
  const bg = new THREE.BoxGeometry(dx, hk, D_);
  const m = new THREE.Mesh(bg, blueMat); m.position.set(0, hk / 2, 0); m.renderOrder = 1;
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(bg), blueEdge); e.position.copy(m.position);
  zoomGroup.add(m, e);
  registerInteractive(m, {
    title: 'The slab S\u2096',
    tooltip: 'Volume ≈ A(x*\u2096)·Δx\u2096',
    body: `This right prism has a face of area A(x*) = ${AreaFun(xm).toFixed(3)} and thickness Δx = ${dx.toFixed(3)}, ` +
      `so its volume is about ${(AreaFun(xm) * dx).toFixed(3)}. Adding such terms gives the Riemann sum Σ A(x*\u2096)Δx\u2096, ` +
      `whose limit is V = ∫ A(x) dx.`
  });

  /* cross-section face + thick black marker line at x*_k */
  const pl = new THREE.Mesh(new THREE.PlaneGeometry(D_, hk), csFaceMat);
  pl.rotation.y = Math.PI / 2; pl.position.set(-dx / 2, hk / 2, 0); pl.renderOrder = 3;
  zoomGroup.add(pl);
  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, hk, 0.05), blackMat);
  mark.position.set(-dx / 2, hk / 2, D_ / 2); mark.renderOrder = 4;
  zoomGroup.add(mark);

  /* axis + dot at x*_k */
  const ya = -0.2, za = D_ / 2;
  const L = 0.85, R = dx / 2 + 1.25;
  zoomGroup.add(polyline([V(-dx / 2 - L, ya, za), V(R, ya, za)], blackLine));
  zoomGroup.add(coneAt(V(R + 0.13, ya, za), V(1, 0, 0), 0.08, 0.26, blackMat));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.075, 18, 14), blackMat);
  dot.position.set(-dx / 2, ya, za); zoomGroup.add(dot);

  /* Δx_k dimension line with inward arrows */
  const yd = -0.72;
  zoomGroup.add(segs([
    [V(-dx / 2, ya - 0.07, za), V(-dx / 2, yd - 0.16, za)],
    [V(dx / 2, 0, za), V(dx / 2, yd - 0.16, za)]
  ], blackLine));
  zoomGroup.add(polyline([V(-dx / 2 - 0.85, yd, za), V(-dx / 2 - 0.2, yd, za)], blackLine));
  zoomGroup.add(polyline([V(dx / 2 + 0.2, yd, za), V(dx / 2 + 0.85, yd, za)], blackLine));
  zoomGroup.add(coneAt(V(-dx / 2 - 0.1, yd, za), V(1, 0, 0), 0.07, 0.22, blackMat));
  zoomGroup.add(coneAt(V(dx / 2 + 0.1, yd, za), V(-1, 0, 0), 0.07, 0.22, blackMat));

  /* tan block arrow of the callout */
  const aLen = 1.45;
  const ar = blockArrow(aLen, 0.26, 0.62, 0.48, tanMat);
  ar.position.set(-dx / 2 - aLen - 0.1, hk * 0.45, za + 0.02);
  zoomGroup.add(ar);
}

/* ── sweeping tan connector (side-by-side only) ─────────────────────────── */
function buildConnector() {
  clearGroup(connGroup);
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx;
  const p0 = V(xm, 0.08, D_ / 2 + 0.2).applyMatrix4(mainGroup.matrixWorld);
  const pts = [
    p0,
    V(p0.x + 0.5, -1.25, p0.z + 0.8),
    V(0.6, -2.15, 1.7),
    V(2.4, -1.7, 1.3),
    V(3.1, -0.85, 1.0)
  ];
  const curve = new THREE.CatmullRomCurve3(pts);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 80, 0.13, 12, false), tanMat);
  connGroup.add(tube);
  const tip = curve.getPointAt(1), tang = curve.getTangentAt(1);
  connGroup.add(coneAt(tip.clone().add(tang.clone().multiplyScalar(0.22)), tang, 0.3, 0.7, tanMat));
  connGroup.add(polyline(curve.getPoints(60), tanEdge));
}

/* ── view layout ────────────────────────────────────────────────────────── */
function applyView() {
  scene.remove(mainGroup); scene.remove(zoomGroup); scene.remove(connGroup);
  if (view === 'solid') {
    mainGroup.scale.setScalar(1); mainGroup.position.set(0, 0, 0);
    scene.add(mainGroup);
  } else if (view === 'zoom') {
    zoomGroup.scale.setScalar(1.6); zoomGroup.position.set(0, 0, 0);
    scene.add(zoomGroup);
  } else {
    mainGroup.scale.setScalar(0.68); mainGroup.position.set(-2.4, 0, 0);
    zoomGroup.scale.setScalar(1.55); zoomGroup.position.set(5.6, 0, 0);
    scene.add(mainGroup); scene.add(zoomGroup); scene.add(connGroup);
  }
}

/* ── labels ─────────────────────────────────────────────────────────────── */
function rebuildLabels() {
  clearLabels();
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx, hk = hFun(xm);
  const inMain = mainGroup.parent === scene, inZoom = zoomGroup.parent === scene;
  const WM = (x, y, z) => V(x, y, z).applyMatrix4(mainGroup.matrixWorld);
  const WZ = (x, y, z) => V(x, y, z).applyMatrix4(zoomGroup.matrixWorld);

  if (inMain) {
    addLabel('<i>S</i>', WM(0.5, hFun(0.5) + 0.25, 0), { fontSize: '15px' });
    const yl = -0.62, zl = D_ / 2 + 0.28;
    addLabel('<i>a</i>', WM(A_, yl, zl), { fontSize: '13px' });
    addLabel('<i>b</i>', WM(B_, yl, zl), { fontSize: '13px' });
    if (n <= 5) {
      for (let i = 1; i < n; i++) addLabel(`<i>x</i><sub>${i}</sub>`, WM(A_ + i * dx, yl, zl), { fontSize: '13px' });
    } else {
      addLabel('<i>x</i><sub>1</sub>', WM(A_ + dx, yl, zl), { fontSize: '13px' });
      addLabel('<i>x</i><sub>2</sub>', WM(A_ + 2 * dx, yl, zl), { fontSize: '13px' });
      addLabel('· · ·', WM(A_ + Math.round(n / 2) * dx, yl, zl), { fontSize: '13px' });
      addLabel('<i>x</i><sub><i>n</i>−1</sub>', WM(B_ - dx, yl, zl), { fontSize: '13px' });
    }
    if (n <= 10) {
      addLabel('<i>S</i><sub>1</sub>', WM(A_ + dx / 2, hFun(A_ + dx / 2) * 0.38, D_ / 2 + 0.02), { fontSize: '13px' });
      if (n >= 2) addLabel('<i>S</i><sub>2</sub>', WM(A_ + 1.5 * dx, hFun(A_ + 1.5 * dx) * 0.42, D_ / 2 + 0.02), { fontSize: '13px' });
    }
    if (n >= 3) addLabel('<i>S<sub>n</sub></i>', WM(B_ - dx / 2, hFun(B_ - dx / 2) * 0.62, D_ / 2 + 0.02), { fontSize: '13px' });
    if (n > 1) addLabel('<i>S<sub>k</sub></i>', WM(xm, hk + 0.2, 0), { fontSize: '12px', color: '#1f5f96', bold: true });
  }

  if (inZoom) {
    const za = D_ / 2;
    addLabel('<i>S<sub>k</sub></i>', WZ(dx / 2, hk * 0.55, 0), { fontSize: '14px', offset: [18, 0] });
    addLabel('<i>x</i>', WZ(dx / 2 + 1.3, 0.12, za), { fontSize: '14px' });
    addLabel('<i>x</i><sup>*</sup><sub><i>k</i></sub>', WZ(-dx / 2, -0.52, za), { fontSize: '13px' });
    addLabel('Δ<i>x<sub>k</sub></i>', WZ(0, -1.12, za), { fontSize: '13px' });
    const cal = addLabel(
      'The cross section here has area <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>).',
      WZ(-dx / 2 - 2.5, hk * 0.45 + 0.95, za), { fontSize: '12px' });
    cal.div.style.background = '#FAE3B0';
    cal.div.style.border = '2px solid #D8A63F';
    cal.div.style.borderRadius = '10px';
    cal.div.style.padding = '6px 9px';
    cal.div.style.whiteSpace = 'normal';
    cal.div.style.width = '106px';
    cal.div.style.textAlign = 'center';
    cal.div.style.lineHeight = '1.35';
  }
}

/* ── readout ────────────────────────────────────────────────────────────── */
function updateReadout() {
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx, Ak = AreaFun(xm);
  let sum = 0;
  for (let i = 0; i < n; i++) sum += AreaFun(A_ + (i + 0.5) * dx) * dx;
  document.getElementById('readout').innerHTML =
    `Δ<i>x<sub>k</sub></i> = (<i>b</i>−<i>a</i>)/<i>n</i> = <b>${dx.toFixed(3)}</b><br>` +
    `<i>x</i><sup>*</sup><sub><i>k</i></sub> = <b>${xm.toFixed(3)}</b>,&nbsp; ` +
    `<i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>) = <b>${Ak.toFixed(3)}</b><br>` +
    `slab volume ≈ <b>${(Ak * dx).toFixed(3)}</b><br>` +
    `Σ <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>)Δ<i>x<sub>k</sub></i> = <b>${sum.toFixed(3)}</b><br>` +
    `<i>V</i> = ∫<sub><i>a</i></sub><sup><i>b</i></sup><i>A</i>(<i>x</i>)d<i>x</i> = <b>${V_EXACT.toFixed(3)}</b><br>` +
    `<span style="color:#888">error = ${Math.abs(sum - V_EXACT).toFixed(4)}</span>`;
}

/* ── full rebuild ───────────────────────────────────────────────────────── */
function rebuild(refit) {
  _interactiveObjects.length = 0;
  syncK();
  buildMain();
  buildZoom();
  applyView();
  scene.updateMatrixWorld(true);
  if (view === 'side') { buildConnector(); scene.updateMatrixWorld(true); }
  rebuildLabels();
  updateReadout();
  const kS = document.getElementById('selectSlab');
  kS.max = String(n); kS.value = String(kIdx + 1);
  document.getElementById('kVal').textContent = String(kIdx + 1);
  document.getElementById('nVal').textContent = String(n);
  if (refit) setCameraView({
    projection: 'orthographic',
    axisScreenAngles: { x: 30, z: 30 },
    heightFraction: view === 'side' ? 0.8 : 0.62
  });
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const nSlider = document.getElementById('slabCount');
nSlider.addEventListener('input', () => { n = +nSlider.value; rebuild(false); });

const kSlider = document.getElementById('selectSlab');
kSlider.addEventListener('input', () => {
  const kk = Math.max(1, Math.min(n, +kSlider.value));
  selFrac = (kk - 0.5) / n;
  rebuild(false);
});

const vBtns = { solid: document.getElementById('btnSolid'), zoom: document.getElementById('btnZoom'), side: document.getElementById('btnSide') };
function setView(v) {
  view = v;
  for (const key in vBtns) vBtns[key].classList.toggle('active', key === v);
  rebuild(true);
}
vBtns.solid.addEventListener('click', () => setView('solid'));
vBtns.zoom.addEventListener('click', () => setView('zoom'));
vBtns.side.addEventListener('click', () => setView('side'));

/* ── drag selection directly on the solid ───────────────────────────────── */
const _rc = new THREE.Raycaster(), _pt = new THREE.Vector2();
let dragging = false;
function pickSlab(ev) {
  if (mainGroup.parent !== scene || !slabMeshes.length) return null;
  const r = canvas.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  const hits = _rc.intersectObjects(slabMeshes, false);
  if (!hits.length) return null;
  return slabMeshes.indexOf(hits[0].object);
}
canvas.addEventListener('pointerdown', (e) => {
  const i = pickSlab(e);
  if (i != null && i >= 0) {
    dragging = true; controls.enabled = false;
    selFrac = (i + 0.5) / n; rebuild(false);
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const i = pickSlab(e);
  if (i != null && i >= 0 && i !== kIdx) { selFrac = (i + 0.5) / n; rebuild(false); }
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── guided walkthrough ─────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The figure', view: 'side', n: 6,
    text: 'Left: the solid S cut into slabs S₁ … Sₙ, one of them highlighted. Right: that kth slab enlarged, with its cross-sectional face of area A(x*ₖ) and thickness Δxₖ. Press Next to build the idea step by step.'
  },
  {
    title: '1. The solid S', view: 'solid', n: 1,
    text: 'The solid S lies along the x-axis from x = a to x = b. Every plane perpendicular to the axis cuts it in a cross section whose area A(x) varies with x.'
  },
  {
    title: '2. Partition into slabs', view: 'solid', n: 6,
    text: 'Cutting at x₁, x₂, …, x₍ₙ₋₁₎ splits S into slabs S₁, …, Sₙ. Each slab is approximated by a prism of constant cross section.'
  },
  {
    title: '3. Zoom on the kth slab', view: 'zoom', n: 6,
    text: 'Isolating the highlighted slab: its face at x*ₖ has area A(x*ₖ) and its thickness is Δxₖ, so its volume is approximately A(x*ₖ)·Δxₖ.'
  },
  {
    title: '4. Adding the slabs up', view: 'side', n: 6,
    text: 'Side by side, the zoomed slab is one term of the sum Σ A(x*ₖ)Δxₖ drawn from the whole solid.'
  },
  {
    title: '5. Refining the partition', view: 'side', n: 30,
    text: 'With n = 30 the slabs become thin wafers, the flat steps vanish, and the sum settles on V = ∫ₐᵇ A(x) dx.'
  }
