  zoomGroup.add(ar);
}

/* ── sweeping tan connector (side-by-side only) ─────────────────────────── */
function buildConnector() {
  clearGroup(connGroup);
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx;
  const p0 = V(xm, 0.08, D_ / 2 + 0.2).applyMatrix4(mainGroup.matrixWorld);
  const pts = [
    p0,
    V(p0.x + 0.5, -1.25, p0.z + 0.8),
    V(0.6, -2.15, 1.7),
    V(2.4, -1.7, 1.3),
    V(3.1, -0.85, 1.0)
  ];
  const curve = new THREE.CatmullRomCurve3(pts);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 80, 0.13, 12, false), tanMat);
  connGroup.add(tube);
  const tip = curve.getPointAt(1), tang = curve.getTangentAt(1);
  connGroup.add(coneAt(tip.clone().add(tang.clone().multiplyScalar(0.22)), tang, 0.3, 0.7, tanMat));
  connGroup.add(polyline(curve.getPoints(60), tanEdge));
}

/* ── view layout ────────────────────────────────────────────────────────── */
function applyView() {
  scene.remove(mainGroup); scene.remove(zoomGroup); scene.remove(connGroup);
  if (view === 'solid') {
    mainGroup.scale.setScalar(1); mainGroup.position.set(0, 0, 0);
    scene.add(mainGroup);
  } else if (view === 'zoom') {
    zoomGroup.scale.setScalar(1.6); zoomGroup.position.set(0, 0, 0);
    scene.add(zoomGroup);
  } else {
    mainGroup.scale.setScalar(0.68); mainGroup.position.set(-2.4, 0, 0);
    zoomGroup.scale.setScalar(1.55); zoomGroup.position.set(5.6, 0, 0);
    scene.add(mainGroup); scene.add(zoomGroup); scene.add(connGroup);
  }
}

/* ── labels ─────────────────────────────────────────────────────────────── */
function rebuildLabels() {
  clearLabels();
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx, hk = hFun(xm);
  const inMain = mainGroup.parent === scene, inZoom = zoomGroup.parent === scene;
  const WM = (x, y, z) => V(x, y, z).applyMatrix4(mainGroup.matrixWorld);
  const WZ = (x, y, z) => V(x, y, z).applyMatrix4(zoomGroup.matrixWorld);

  if (inMain) {
    addLabel('<i>S</i>', WM(0.5, hFun(0.5) + 0.25, 0), { fontSize: '15px' });
    const yl = -0.62, zl = D_ / 2 + 0.28;
    addLabel('<i>a</i>', WM(A_, yl, zl), { fontSize: '13px' });
    addLabel('<i>b</i>', WM(B_, yl, zl), { fontSize: '13px' });
    if (n <= 5) {
      for (let i = 1; i < n; i++) addLabel(`<i>x</i><sub>${i}</sub>`, WM(A_ + i * dx, yl, zl), { fontSize: '13px' });
    } else {
      addLabel('<i>x</i><sub>1</sub>', WM(A_ + dx, yl, zl), { fontSize: '13px' });
      addLabel('<i>x</i><sub>2</sub>', WM(A_ + 2 * dx, yl, zl), { fontSize: '13px' });
      addLabel('· · ·', WM(A_ + Math.round(n / 2) * dx, yl, zl), { fontSize: '13px' });
      addLabel('<i>x</i><sub><i>n</i>−1</sub>', WM(B_ - dx, yl, zl), { fontSize: '13px' });
    }
    if (n <= 10) {
      addLabel('<i>S</i><sub>1</sub>', WM(A_ + dx / 2, hFun(A_ + dx / 2) * 0.38, D_ / 2 + 0.02), { fontSize: '13px' });
      if (n >= 2) addLabel('<i>S</i><sub>2</sub>', WM(A_ + 1.5 * dx, hFun(A_ + 1.5 * dx) * 0.42, D_ / 2 + 0.02), { fontSize: '13px' });
    }
    if (n >= 3) addLabel('<i>S<sub>n</sub></i>', WM(B_ - dx / 2, hFun(B_ - dx / 2) * 0.62, D_ / 2 + 0.02), { fontSize: '13px' });
    if (n > 1) addLabel('<i>S<sub>k</sub></i>', WM(xm, hk + 0.2, 0), { fontSize: '12px', color: '#1f5f96', bold: true });
  }

  if (inZoom) {
    const za = D_ / 2;
    addLabel('<i>S<sub>k</sub></i>', WZ(dx / 2, hk * 0.55, 0), { fontSize: '14px', offset: [18, 0] });
    addLabel('<i>x</i>', WZ(dx / 2 + 1.3, 0.12, za), { fontSize: '14px' });
    addLabel('<i>x</i><sup>*</sup><sub><i>k</i></sub>', WZ(-dx / 2, -0.52, za), { fontSize: '13px' });
    addLabel('Δ<i>x<sub>k</sub></i>', WZ(0, -1.12, za), { fontSize: '13px' });
    const cal = addLabel(
      'The cross section here has area <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>).',
      WZ(-dx / 2 - 2.5, hk * 0.45 + 0.95, za), { fontSize: '12px' });
    cal.div.style.background = '#FAE3B0';
    cal.div.style.border = '2px solid #D8A63F';
    cal.div.style.borderRadius = '10px';
    cal.div.style.padding = '6px 9px';
    cal.div.style.whiteSpace = 'normal';
    cal.div.style.width = '106px';
    cal.div.style.textAlign = 'center';
    cal.div.style.lineHeight = '1.35';
  }
}

/* ── readout ────────────────────────────────────────────────────────────── */
function updateReadout() {
  const dx = (B_ - A_) / n, xm = A_ + (kIdx + 0.5) * dx, Ak = AreaFun(xm);
  let sum = 0;
  for (let i = 0; i < n; i++) sum += AreaFun(A_ + (i + 0.5) * dx) * dx;
  document.getElementById('readout').innerHTML =
    `Δ<i>x<sub>k</sub></i> = (<i>b</i>−<i>a</i>)/<i>n</i> = <b>${dx.toFixed(3)}</b><br>` +
    `<i>x</i><sup>*</sup><sub><i>k</i></sub> = <b>${xm.toFixed(3)}</b>,&nbsp; ` +
    `<i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>) = <b>${Ak.toFixed(3)}</b><br>` +
    `slab volume ≈ <b>${(Ak * dx).toFixed(3)}</b><br>` +
    `Σ <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>)Δ<i>x<sub>k</sub></i> = <b>${sum.toFixed(3)}</b><br>` +
    `<i>V</i> = ∫<sub><i>a</i></sub><sup><i>b</i></sup><i>A</i>(<i>x</i>)d<i>x</i> = <b>${V_EXACT.toFixed(3)}</b><br>` +
    `<span style="color:#888">error = ${Math.abs(sum - V_EXACT).toFixed(4)}</span>`;
}

/* ── full rebuild ───────────────────────────────────────────────────────── */
function rebuild(refit) {
  _interactiveObjects.length = 0;
  syncK();
  buildMain();
  buildZoom();
  applyView();
  scene.updateMatrixWorld(true);
  if (view === 'side') { buildConnector(); scene.updateMatrixWorld(true); }
  rebuildLabels();
  updateReadout();
  const kS = document.getElementById('selectSlab');
  kS.max = String(n); kS.value = String(kIdx + 1);
  document.getElementById('kVal').textContent = String(kIdx + 1);
  document.getElementById('nVal').textContent = String(n);
  if (refit) setCameraView({
    projection: 'orthographic',
    axisScreenAngles: { x: 30, z: 30 },
    heightFraction: view === 'side' ? 0.8 : 0.62
  });
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const nSlider = document.getElementById('slabCount');
nSlider.addEventListener('input', () => { n = +nSlider.value; rebuild(false); });

const kSlider = document.getElementById('selectSlab');
kSlider.addEventListener('input', () => {
  const kk = Math.max(1, Math.min(n, +kSlider.value));
  selFrac = (kk - 0.5) / n;
  rebuild(false);
});

const vBtns = { solid: document.getElementById('btnSolid'), zoom: document.getElementById('btnZoom'), side: document.getElementById('btnSide') };
function setView(v) {
  view = v;
  for (const key in vBtns) vBtns[key].classList.toggle('active', key === v);
  rebuild(true);
}
vBtns.solid.addEventListener('click', () => setView('solid'));
vBtns.zoom.addEventListener('click', () => setView('zoom'));
vBtns.side.addEventListener('click', () => setView('side'));

/* ── drag selection directly on the solid ───────────────────────────────── */
const _rc = new THREE.Raycaster(), _pt = new THREE.Vector2();
let dragging = false;
function pickSlab(ev) {
  if (mainGroup.parent !== scene || !slabMeshes.length) return null;
  const r = canvas.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  const hits = _rc.intersectObjects(slabMeshes, false);
  if (!hits.length) return null;
  return slabMeshes.indexOf(hits[0].object);
}
canvas.addEventListener('pointerdown', (e) => {
  const i = pickSlab(e);
  if (i != null && i >= 0) {
    dragging = true; controls.enabled = false;
    selFrac = (i + 0.5) / n; rebuild(false);
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const i = pickSlab(e);
  if (i != null && i >= 0 && i !== kIdx) { selFrac = (i + 0.5) / n; rebuild(false); }
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── guided walkthrough ─────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The figure', view: 'side', n: 6,
    text: 'Left: the solid S cut into slabs S₁ … Sₙ, one of them highlighted. Right: that kth slab enlarged, with its cross-sectional face of area A(x*ₖ) and thickness Δxₖ. Press Next to build the idea step by step.'
  },
  {
    title: '1. The solid S', view: 'solid', n: 1,
    text: 'The solid S lies along the x-axis from x = a to x = b. Every plane perpendicular to the axis cuts it in a cross section whose area A(x) varies with x.'
  },
  {
    title: '2. Partition into slabs', view: 'solid', n: 6,
    text: 'Cutting at x₁, x₂, …, x₍ₙ₋₁₎ splits S into slabs S₁, …, Sₙ. Each slab is approximated by a prism of constant cross section.'
  },
  {
    title: '3. Zoom on the kth slab', view: 'zoom', n: 6,
    text: 'Isolating the highlighted slab: its face at x*ₖ has area A(x*ₖ) and its thickness is Δxₖ, so its volume is approximately A(x*ₖ)·Δxₖ.'
  },
  {
    title: '4. Adding the slabs up', view: 'side', n: 6,
    text: 'Side by side, the zoomed slab is one term of the sum Σ A(x*ₖ)Δxₖ drawn from the whole solid.'
  },
  {
    title: '5. Refining the partition', view: 'side', n: 30,
    text: 'With n = 30 the slabs become thin wafers, the flat steps vanish, and the sum settles on V = ∫ₐᵇ A(x) dx.'
  }
];
let stepIdx = 0, tweenTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  if (view !== s.view) { view = s.view; for (const key in vBtns) vBtns[key].classList.toggle('active', key === s.view); }
  if (tweenTimer) { clearInterval(tweenTimer); tweenTimer = null; }
  const target = s.n;
  tweenTimer = setInterval(() => {
    if (n === target) { clearInterval(tweenTimer); tweenTimer = null; return; }
    const step = Math.max(1, Math.round(Math.abs(target - n) / 6));
    n += Math.sign(target - n) * step;
    if ((target - n) * Math.sign(target - n || 1) < 0) n = target;
    n = Math.max(1, Math.min(40, n));
    nSlider.value = String(n);
    rebuild(false);
  }, 45);
  nSlider.value = String(n);
  rebuild(true);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

