// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
   solid S, slab pieces  -> ExtrudeGeometry of profile {x∈[xl,xr], 0≤y≤h(x)} depth d  pale pink #F7CFCF
   highlighted slab      -> same extrusion, blue #7FB3DC + blue polyline outline #3C7CB4
   red silhouette of S   -> Line/LineSegments  #E23B3B  (top front+back curves, ends, bottom)
   partition cut lines   -> LineSegments  #1A1A1A  (vertical on front face + across top surface)
   prism-mode ghost      -> ExtrudeGeometry of full profile, pink 0.18, depthWrite false
   prism-mode slabs      -> flat-topped extrusion + EdgesGeometry
   base x-axis           -> Line + ConeGeometry head + tick LineSegments (black)
   zoom slab S_k         -> BoxGeometry(Δx,h,d) blue + EdgesGeometry blue, group scale 2
   neighbour shells      -> EdgesGeometry boxes, gray #9A9A9A
   cross-section face    -> PlaneGeometry(d,h) facing −X, blue tint
   thick cross-section   -> two thin BoxGeometry rods (front vertical + top), black
   dot at x*_k           -> SphereGeometry(0.07) black
   Δx_k dimension        -> Lines + two ConeGeometry arrows pointing inward
   callout               -> HTML label (#FAE3B0 / #D8A63F) + ExtrudeGeometry block arrow, tan
   sweeping connector    -> tapered ribbon BufferGeometry + triangle head, tan #F1DCAA
   all text              -> addLabel HTML overlays
──────────────────────────────────────────────────────────────────────────── */

const A_ = -3, B_ = 3, D_ = 1.6;
const hFun = x => 0.7 + 1.5 * Math.sqrt(Math.max(0, (x - A_) / (B_ - A_)));
const AreaFun = x => D_ * hFun(x);

let V_EXACT = 0;
{ const N = 20000, dxe = (B_ - A_) / N; for (let i = 0; i < N; i++) V_EXACT += AreaFun(A_ + (i + 0.5) * dxe) * dxe; }

/* ── materials ──────────────────────────────────────────────────────────── */
const faceOpts = { transparent: true, side: THREE.FrontSide, polygonOffset: true, polygonOffsetFactor: 1.5, polygonOffsetUnits: 1 };
const pinkMat = new THREE.MeshBasicMaterial({ color: 0xF7CFCF, opacity: 0.78, ...faceOpts });
const blueMat = new THREE.MeshBasicMaterial({ color: 0x7FB3DC, opacity: 0.82, ...faceOpts });
const ghostMat = new THREE.MeshBasicMaterial({ color: 0xF7CFCF, transparent: true, opacity: 0.18, depthWrite: false, side: THREE.DoubleSide });
const redEdge = new THREE.LineBasicMaterial({ color: 0xE23B3B });
const cutEdge = new THREE.LineBasicMaterial({ color: 0x1A1A1A, transparent: true, opacity: 0.92 });
const cutEdgeFaint = new THREE.LineBasicMaterial({ color: 0x1A1A1A, transparent: true, opacity: 0.4 });
const blueEdge = new THREE.LineBasicMaterial({ color: 0x3C7CB4 });
const grayEdge = new THREE.LineBasicMaterial({ color: 0x9A9A9A });
const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
const csFaceMat = new THREE.MeshBasicMaterial({ color: 0x4A90C8, transparent: true, opacity: 0.45, depthWrite: false, side: THREE.DoubleSide });
const tanMat = new THREE.MeshBasicMaterial({ color: 0xF1DCAA, side: THREE.DoubleSide });
const tanEdge = new THREE.LineBasicMaterial({ color: 0xB9B0A0 });
const invisMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });

/* ── groups ─────────────────────────────────────────────────────────────── */
const mainGroup = new THREE.Group();
const zoomGroup = new THREE.Group();
const connGroup = new THREE.Group();

/* ── helpers ────────────────────────────────────────────────────────────── */
const V = (x, y, z) => new THREE.Vector3(x, y, z);
function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse && c.traverse(o => { if (o.geometry) o.geometry.dispose(); });
  }
}
function clearLabels() { for (const e of _labels) e.div.remove(); _labels.length = 0; }
function polyline(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function segs(pairs, mat) {
  const p = []; for (const q of pairs) { p.push(q[0], q[1]); }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(p), mat);
}
function coneAt(pos, dir, r, h, mat) {
  const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, 18), mat);
  c.position.copy(pos);
  c.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize());
  return c;
}
function rod(a, b, r, mat) {                       // "thick line" as a thin box
  const dir = b.clone().sub(a), len = dir.length();
  const g = new THREE.BoxGeometry(r, len, r);
  const m = new THREE.Mesh(g, mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dir.normalize());
  return m;
}
function blockArrow(len, shaftH, headH, headL, mat) {
  const s = new THREE.Shape();
  s.moveTo(0, -shaftH / 2); s.lineTo(len - headL, -shaftH / 2); s.lineTo(len - headL, -headH / 2);
  s.lineTo(len, 0); s.lineTo(len - headL, headH / 2); s.lineTo(len - headL, shaftH / 2);
  s.lineTo(0, shaftH / 2); s.closePath();
  return new THREE.Mesh(new THREE.ExtrudeGeometry(s, { depth: 0.04, bevelEnabled: false }), mat);
}
function anchor(group, x, y, z) {                  // invisible, but counts for camera fit
  const m = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.01, 0.01), invisMat);
  m.position.set(x, y, z); group.add(m); return m;
}

/* ── state ──────────────────────────────────────────────────────────────── */
let n = 6;
let kIdx = 2;                 // 3rd slab, as printed
let view = 'side';
let prismMode = false;
const slabMeshes = [];
const dxOf = () => (B_ - A_) / n;
const xStar = () => A_ + kIdx * dxOf();            // sample point = left edge of slab k
function syncK() { kIdx = Math.max(0, Math.min(n - 1, kIdx)); }

/* ── one slab of the true solid (or its flat-topped prism) ──────────────── */
function slabGeom(xl, xr, flat) {
  const cx = (xl + xr) / 2, w = (xr - xl) / 2;
  const s = new THREE.Shape();
  s.moveTo(-w, 0); s.lineTo(w, 0);
  if (flat) { const hh = hFun(xl); s.lineTo(w, hh); s.lineTo(-w, hh); }
  else { const M = 14; for (let i = M; i >= 0; i--) { const t = -w + 2 * w * i / M; s.lineTo(t, hFun(cx + t)); } }
  s.closePath();
  const g = new THREE.ExtrudeGeometry(s, { depth: D_, bevelEnabled: false });
  g.translate(0, 0, -D_ / 2);
  return { g, cx };
}

/* ── left panel: the solid S cut into slabs ─────────────────────────────── */
function buildMain() {
  clearGroup(mainGroup);
  slabMeshes.length = 0;
  const dx = dxOf();

  /* faint ghost of the true solid, only when prisms replace the real pieces */
  if (prismMode) {
    const sh = new THREE.Shape();
    sh.moveTo(A_, 0); sh.lineTo(B_, 0);
    const NS = 80;
    for (let i = NS; i >= 0; i--) { const x = A_ + (B_ - A_) * i / NS; sh.lineTo(x, hFun(x)); }
    sh.closePath();
    const gg = new THREE.ExtrudeGeometry(sh, { depth: D_, bevelEnabled: false });
    gg.translate(0, 0, -D_ / 2);
    const ghost = new THREE.Mesh(gg, ghostMat); ghost.renderOrder = -2;
    mainGroup.add(ghost);
  }

  /* slab bodies */
  for (let i = 0; i < n; i++) {
    const xl = A_ + i * dx, xr = xl + dx;
    const { g, cx } = slabGeom(xl, xr, prismMode);
    const mesh = new THREE.Mesh(g, i === kIdx ? blueMat : pinkMat);
    mesh.position.x = cx;
    mesh.renderOrder = 1;
    mainGroup.add(mesh);
    slabMeshes.push(mesh);
    const xs = xl;
    registerInteractive(mesh, {
      title: `Slab S${i + 1}`,
      tooltip: `S${i + 1}:  A(x*) ≈ ${AreaFun(xs).toFixed(2)},  Δx = ${dx.toFixed(2)}`,
      body: `Slab S${i + 1} sits over [${xl.toFixed(2)}, ${xr.toFixed(2)}]. With the sample point ` +
        `x* = ${xs.toFixed(2)} its cross section has area A(x*) = ${AreaFun(xs).toFixed(3)} and its ` +
        `thickness is Δx = ${dx.toFixed(3)}, so its volume is about ${(AreaFun(xs) * dx).toFixed(3)}.`,
      onClick: () => { kIdx = i; rebuild(false); }
    });
    if (prismMode) {
      const e = new THREE.LineSegments(new THREE.EdgesGeometry(g), i === kIdx ? blueEdge : (n > 12 ? cutEdgeFaint : cutEdge));
      e.position.x = cx; mainGroup.add(e);
    }
  }

  /* red silhouette of the true solid */
  const NS = 90, topF = [], topB = [];
  for (let i = 0; i <= NS; i++) { const x = A_ + (B_ - A_) * i / NS; topF.push(V(x, hFun(x), D_ / 2)); topB.push(V(x, hFun(x), -D_ / 2)); }
  mainGroup.add(polyline(topF, redEdge), polyline(topB, redEdge));
  mainGroup.add(segs([
    [V(A_, 0, D_ / 2), V(B_, 0, D_ / 2)], [V(A_, 0, -D_ / 2), V(B_, 0, -D_ / 2)],
    [V(A_, 0, -D_ / 2), V(A_, 0, D_ / 2)], [V(B_, 0, -D_ / 2), V(B_, 0, D_ / 2)],
    [V(A_, 0, D_ / 2), V(A_, hFun(A_), D_ / 2)], [V(A_, 0, -D_ / 2), V(A_, hFun(A_), -D_ / 2)],
    [V(B_, 0, D_ / 2), V(B_, hFun(B_), D_ / 2)], [V(B_, 0, -D_ / 2), V(B_, hFun(B_), -D_ / 2)],
    [V(A_, hFun(A_), -D_ / 2), V(A_, hFun(A_), D_ / 2)], [V(B_, hFun(B_), -D_ / 2), V(B_, hFun(B_), D_ / 2)]
  ], redEdge));

  /* black partition cuts: down the front face and across the top surface */
  if (!prismMode) {
    const cuts = [];
    for (let i = 1; i < n; i++) {
      const x = A_ + i * dx, hh = hFun(x);
      cuts.push([V(x, 0, D_ / 2), V(x, hh, D_ / 2)]);
      cuts.push([V(x, hh, D_ / 2), V(x, hh, -D_ / 2)]);
    }
    if (cuts.length) mainGroup.add(segs(cuts, n > 12 ? cutEdgeFaint : cutEdge));
  }

  /* blue outline around the highlighted piece */
  if (!prismMode) {
    const xl = A_ + kIdx * dx, xr = xl + dx, M = 16;
    for (const z of [D_ / 2, -D_ / 2]) {
      const p = [V(xl, 0, z), V(xl, hFun(xl), z)];
      for (let i = 0; i <= M; i++) { const x = xl + (xr - xl) * i / M; p.push(V(x, hFun(x), z)); }
      p.push(V(xr, 0, z), V(xl, 0, z));
      mainGroup.add(polyline(p, blueEdge));
    }
    mainGroup.add(segs([
      [V(xl, hFun(xl), D_ / 2), V(xl, hFun(xl), -D_ / 2)],
      [V(xr, hFun(xr), D_ / 2), V(xr, hFun(xr), -D_ / 2)]
    ], blueEdge));
  }

  /* x-axis with ticks and arrowhead, drawn in front of the solid */
  const ya = -0.15, za = D_ / 2 + 0.35;
  mainGroup.add(polyline([V(-4, ya, za), V(4, ya, za)], blackLine));
  mainGroup.add(coneAt(V(4.13, ya, za), V(1, 0, 0), 0.085, 0.26, blackMat));
  const tk = [];
  for (let i = 0; i <= n; i++) { const x = A_ + i * dx; tk.push([V(x, ya - 0.11, za), V(x, ya + 0.11, za)]); }
  mainGroup.add(segs(tk, blackLine));
}

/* ── right panel: the kth slab enlarged ─────────────────────────────────── */
function buildZoom() {
  clearGroup(zoomGroup);
  const dx = dxOf(), xs = xStar(), hk = hFun(xs);

  /* gray wireframe shells of the neighbouring slabs */
  for (const off of [-1, 1]) {
    const j = kIdx + off; if (j < 0 || j >= n) continue;
    const hj = hFun(A_ + j * dx);
    const g = new THREE.BoxGeometry(dx, hj, D_);
    const e = new THREE.LineSegments(new THREE.EdgesGeometry(g), grayEdge);
    e.position.set(off * dx, hj / 2, 0);
    zoomGroup.add(e); g.dispose();
  }

  /* the slab itself: a right prism of thickness Δx */
  const bg = new THREE.BoxGeometry(dx, hk, D_);
  const m = new THREE.Mesh(bg, blueMat); m.position.set(0, hk / 2, 0); m.renderOrder = 1;
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(bg), blueEdge); e.position.copy(m.position);
  zoomGroup.add(m, e);
  registerInteractive(m, {
    title: 'The slab S\u2096',
    tooltip: 'Volume ≈ A(x*\u2096)·Δx\u2096',
    body: `This right prism has a cross-sectional face of area A(x*\u2096) = ${AreaFun(xs).toFixed(3)} and ` +
      `thickness Δx\u2096 = ${dx.toFixed(3)}, so its volume is about ${(AreaFun(xs) * dx).toFixed(3)}. ` +
      `Summing such terms gives Σ A(x*\u2096)Δx\u2096, whose limit is V = ∫ A(x) dx.`
  });

  /* the cross-section face at x*_k, with its thick black outline */
  const pl = new THREE.Mesh(new THREE.PlaneGeometry(D_, hk), csFaceMat);
  pl.rotation.y = Math.PI / 2; pl.position.set(-dx / 2, hk / 2, 0); pl.renderOrder = 3;
  zoomGroup.add(pl);
  const r = 0.05;
  const v1 = rod(V(-dx / 2, 0, D_ / 2), V(-dx / 2, hk, D_ / 2), r, blackMat);
  const v2 = rod(V(-dx / 2, hk, D_ / 2), V(-dx / 2, hk, -D_ / 2), r, blackMat);
  v1.renderOrder = 4; v2.renderOrder = 4;
  zoomGroup.add(v1, v2);

  /* axis, dot at x*_k */
  const ya = -0.28, za = D_ / 2;
  zoomGroup.add(polyline([V(-dx / 2 - 1.15, ya, za), V(dx / 2 + 1.35, ya, za)], blackLine));
  zoomGroup.add(coneAt(V(dx / 2 + 1.47, ya, za), V(1, 0, 0), 0.075, 0.24, blackMat));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.075, 18, 14), blackMat);
  dot.position.set(-dx / 2, ya, za); zoomGroup.add(dot);

  /* Δx_k dimension line with inward arrows */
  const yd = -1.05;
  zoomGroup.add(segs([
    [V(-dx / 2, -0.75, za), V(-dx / 2, yd - 0.22, za)],
    [V(dx / 2, -0.75, za), V(dx / 2, yd - 0.22, za)]
  ], blackLine));
  zoomGroup.add(polyline([V(-dx / 2 - 1.0, yd, za), V(-dx / 2 - 0.16, yd, za)], blackLine));
  zoomGroup.add(polyline([V(dx / 2 + 0.16, yd, za), V(dx / 2 + 1.0, yd, za)], blackLine));
  zoomGroup.add(coneAt(V(-dx / 2 - 0.09, yd, za), V(1, 0, 0), 0.07, 0.2, blackMat));
  zoomGroup.add(coneAt(V(dx / 2 + 0.09, yd, za), V(-1, 0, 0), 0.07, 0.2, blackMat));

  /* thick tan callout arrow pointing at the cross section */
  const aLen = 1.42;
  const ar = blockArrow(aLen, 0.30, 0.78, 0.5, tanMat);
  ar.position.set(-dx / 2 - aLen - 0.08, hk * 0.44, za + 0.05);
  zoomGroup.add(ar);

  /* reserve room for the HTML callout box */
  anchor(zoomGroup, -dx / 2 - 3.0, hk * 0.78 + 0.55, za);
  anchor(zoomGroup, -dx / 2 - 3.0, hk * 0.78 - 0.55, za);
}

/* ── sweeping tan connector (side-by-side only) ─────────────────────────── */
function ribbon(p0, p1, p2, w0, w1, z) {
  const N = 52, pos = [], idx = [], left = [], right = [];
  let ex = 0, ey = 0, etx = 1, ety = 0;
  for (let i = 0; i <= N; i++) {
    const t = i / N, mt = 1 - t;
    const x = mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0];
    const y = mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1];
    let tx = 2 * mt * (p1[0] - p0[0]) + 2 * t * (p2[0] - p1[0]);
    let ty = 2 * mt * (p1[1] - p0[1]) + 2 * t * (p2[1] - p1[1]);
    const L = Math.hypot(tx, ty) || 1; tx /= L; ty /= L;
    const w = w0 + (w1 - w0) * t;
    pos.push(x - ty * w, y + tx * w, z, x + ty * w, y - tx * w, z);
    left.push(V(x - ty * w, y + tx * w, z)); right.push(V(x + ty * w, y - tx * w, z));
    if (i < N) { const a = 2 * i; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
    ex = x; ey = y; etx = tx; ety = ty;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  const mesh = new THREE.Mesh(g, tanMat);
  /* arrowhead */
  const hw = w1 * 2.1, hl = 1.0;
  const hg = new THREE.BufferGeometry();
  hg.setAttribute('position', new THREE.Float32BufferAttribute([
    ex - ety * hw, ey + etx * hw, z,
    ex + ety * hw, ey - etx * hw, z,
    ex + etx * hl, ey + ety * hl, z
  ], 3));
  const head = new THREE.Mesh(hg, tanMat);
  return { mesh, head, left, right };
}

function buildConnector() {
  clearGroup(connGroup);
  const dx = dxOf(), xs = xStar() + dx / 2;
  const p0 = [mainGroup.position.x + xs, -1.05];
  const p2 = [zoomGroup.position.x - (dx / 2 + 1.35) * zoomGroup.scale.x, -1.15];
  const p1 = [(p0[0] + p2[0]) / 2 + 0.6, -3.5];
  const z = D_ / 2 + 0.7;
  const rb = ribbon(p0, p1, p2, 0.13, 0.30, z);
  connGroup.add(rb.mesh, rb.head);
  connGroup.add(polyline(rb.left, tanEdge), polyline(rb.right.slice().reverse(), tanEdge));
}

/* ── layout of the two panels ───────────────────────────────────────────── */
function applyView() {
  scene.remove(mainGroup); scene.remove(zoomGroup); scene.remove(connGroup);
  if (view === 'solid') {
    mainGroup.scale.setScalar(1); mainGroup.position.set(0, 0, 0);
    scene.add(mainGroup);
  } else if (view === 'zoom') {
    zoomGroup.scale.setScalar(2.0); zoomGroup.position.set(0, 0, 0);
    scene.add(zoomGroup);
  } else {
    mainGroup.scale.setScalar(1); mainGroup.position.set(-5.4, 0, 0);
    zoomGroup.scale.setScalar(2.0); zoomGroup.position.set(6.3, 0.15, 0);
    scene.add(mainGroup); scene.add(zoomGroup); scene.add(connGroup);
  }
}

/* ── labels ─────────────────────────────────────────────────────────────── */
function rebuildLabels() {
  clearLabels();
  const dx = dxOf(), xs = xStar(), hk = hFun(xs);
  const inMain = mainGroup.parent === scene, inZoom = zoomGroup.parent === scene;
  const WM = (x, y, z) => V(x, y, z).applyMatrix4(mainGroup.matrixWorld);
  const WZ = (x, y, z) => V(x, y, z).applyMatrix4(zoomGroup.matrixWorld);

  if (inMain) {
    addLabel('<i>S</i>', WM(0.7, hFun(0.7) + 0.12, -0.15), { fontSize: '15px' });
    const yl = -0.62, zl = D_ / 2 + 0.35;
    addLabel('<i>a</i>', WM(A_, yl, zl), { fontSize: '14px' });
    addLabel('<i>b</i>', WM(B_, yl, zl), { fontSize: '14px' });
    if (n <= 8) {
      for (let i = 1; i < n; i++) addLabel(`<i>x</i><sub>${i}</sub>`, WM(A_ + i * dx, yl, zl), { fontSize: '14px' });
    } else {
      addLabel('<i>x</i><sub>1</sub>', WM(A_ + dx, yl, zl), { fontSize: '14px' });
      addLabel('<i>x</i><sub>2</sub>', WM(A_ + 2 * dx, yl, zl), { fontSize: '14px' });
      addLabel('· · ·', WM(0, yl, zl), { fontSize: '14px' });
      addLabel('<i>x</i><sub><i>n</i>−1</sub>', WM(B_ - dx, yl, zl), { fontSize: '14px' });
    }
    if (n <= 12) {
      addLabel('<i>S</i><sub>1</sub>', WM(A_ + dx / 2, hFun(A_ + dx / 2) * 0.33, D_ / 2 + 0.02), { fontSize: '14px' });
      if (n >= 2) addLabel('<i>S</i><sub>2</sub>', WM(A_ + 1.5 * dx, hFun(A_ + 1.5 * dx) * 0.36, D_ / 2 + 0.02), { fontSize: '14px' });
      if (n >= 3) addLabel('<i>S<sub>n</sub></i>', WM(B_ - dx / 2, hFun(B_ - dx / 2) * 0.72, D_ / 2 + 0.02), { fontSize: '14px' });
    }
    if (view === 'solid' && n > 1)
      addLabel('<i>S<sub>k</sub></i>', WM(xs + dx / 2, hFun(xs + dx / 2) + 0.22, 0), { fontSize: '13px', color: '#1f5f96', bold: true });
  }

  if (inZoom) {
    const za = D_ / 2;
    addLabel('<i>S<sub>k</sub></i>', WZ(dx / 2, hk * 0.45, 0), { fontSize: '15px', offset: [24, 0] });
    addLabel('<i>x</i>', WZ(dx / 2 + 1.25, -0.05, za), { fontSize: '15px', offset: [0, -10] });
    addLabel('<i>x</i><sup>*</sup><sub><i>k</i></sub>', WZ(-dx / 2, -0.62, za), { fontSize: '14px' });
    addLabel('Δ<i>x<sub>k</sub></i>', WZ(0, -1.05, za), { fontSize: '14px', offset: [0, 1] });
    const cal = addLabel(
      'The cross section here has area <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>).',
      WZ(-dx / 2 - 1.95, hk * 0.78 + 0.28, za), { fontSize: '13px' });
    cal.div.style.background = '#FAE3B0';
    cal.div.style.border = '2px solid #D8A63F';
    cal.div.style.borderRadius = '12px';
    cal.div.style.padding = '7px 10px';
    cal.div.style.whiteSpace = 'normal';
    cal.div.style.width = '112px';
    cal.div.style.textAlign = 'center';
    cal.div.style.lineHeight = '1.4';
  }
}

/* ── readout ────────────────────────────────────────────────────────────── */
function updateReadout() {
  const dx = dxOf(), xs = xStar(), Ak = AreaFun(xs);
  let sum = 0;
  for (let i = 0; i < n; i++) sum += AreaFun(A_ + i * dx) * dx;
  document.getElementById('readout').innerHTML =
    `Δ<i>x<sub>k</sub></i> = (<i>b</i>−<i>a</i>)/<i>n</i> = <b>${dx.toFixed(3)}</b><br>` +
    `<i>x</i><sup>*</sup><sub><i>k</i></sub> = <b>${xs.toFixed(3)}</b>,&nbsp; ` +
    `<i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>) = <b>${Ak.toFixed(3)}</b><br>` +
    `slab volume ≈ <b>${(Ak * dx).toFixed(3)}</b><br>` +
    `Σ <i>A</i>(<i>x</i><sup>*</sup><sub><i>k</i></sub>)Δ<i>x<sub>k</sub></i> = <b>${sum.toFixed(3)}</b><br>` +
    `<i>V</i> = ∫<sub><i>a</i></sub><sup><i>b</i></sup><i>A</i>(<i>x</i>)d<i>x</i> = <b>${V_EXACT.toFixed(3)}</b><br>` +
    `<span style="color:#888">error = ${Math.abs(sum - V_EXACT).toFixed(4)}</span>`;
}

/* ── full rebuild ───────────────────────────────────────────────────────── */
function rebuild(refit) {
  _interactiveObjects.length = 0;
  syncK();
  buildMain();
  buildZoom();
  applyView();
  scene.updateMatrixWorld(true);
  if (view === 'side') { buildConnector(); scene.updateMatrixWorld(true); }
  else clearGroup(connGroup);
  rebuildLabels();
  updateReadout();
