}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const nSlider = document.getElementById('slabCount');
nSlider.addEventListener('input', () => {
  const frac = (kIdx + 0.5) / n;
  n = +nSlider.value;
  kIdx = Math.max(0, Math.min(n - 1, Math.floor(frac * n)));
  rebuild(false);
});

const kSlider = document.getElementById('selectSlab');
kSlider.addEventListener('input', () => {
  kIdx = Math.max(0, Math.min(n - 1, (+kSlider.value) - 1));
  rebuild(false);
});

document.getElementById('prismChk').addEventListener('change', (e) => {
  prismMode = e.target.checked; rebuild(false);
});

const vBtns = { solid: document.getElementById('btnSolid'), zoom: document.getElementById('btnZoom'), side: document.getElementById('btnSide') };
function setView(v) {
