/* ── drag the selection along x, directly on the solid ──────────────────── */
const _rc = new THREE.Raycaster(), _pt = new THREE.Vector2();
let dragging = false;
function pickSlab(ev) {
  if (mainGroup.parent !== scene || !slabMeshes.length) return -1;
  const r = canvas.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  const hits = _rc.intersectObjects(slabMeshes, false);
  if (!hits.length) return -1;
  return slabMeshes.indexOf(hits[0].object);
}
canvas.addEventListener('pointerdown', (e) => {
  const i = pickSlab(e);
  if (i >= 0) { dragging = true; controls.enabled = false; if (i !== kIdx) { kIdx = i; rebuild(false); } }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const i = pickSlab(e);
  if (i >= 0 && i !== kIdx) { kIdx = i; rebuild(false); }
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── guided walkthrough ─────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The figure', view: 'side', n: 6,
    text: 'Left: the solid S cut into slabs S₁ … Sₙ, one of them highlighted. Right: that kth slab enlarged as a right prism, with its cross-sectional face of area A(x*ₖ) and thickness Δxₖ. Press Next to build the idea step by step.'
  },
